import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"OpenRouter (BYOK Provider)","description":"","frontmatter":{"title":"OpenRouter (BYOK Provider)"},"headers":[],"relativePath":"providers/openrouter.md","filePath":"providers/openrouter.md"}`),a={name:`providers/openrouter.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="openrouter-mode-byok" tabindex="-1">OpenRouter (Mode BYOK) <a class="header-anchor" href="#openrouter-mode-byok" aria-label="Permalink to “OpenRouter (Mode BYOK)”">​</a></h1><p><strong>OpenRouter</strong> itu bukan provider model, melainkan <strong>agregator</strong>: satu pintu API seragam ke <strong>ratusan model</strong> dari banyak lab berbeda — dari Gemini sampai Claude sampai model open-source — dan semuanya bisa diakses dengan <strong>satu key untuk semuanya</strong>. Harganya <em>pass-through</em> tanpa markup, dan kalau satu provider sedang gangguan, OpenRouter otomatis <em>fallback</em> ke provider lain untuk model yang sama → <em>uptime</em> lebih baik. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Daftar model, varian, dan aturan limit OpenRouter berubah cukup sering. Halaman ini mengajarkan <strong>cara</strong> yang benar — angka yang diberi tanda &quot;≈&quot; adalah <em>rule of thumb</em> yang bisa bergeser. Selalu cek halaman resmi <a href="https://openrouter.ai/docs" target="_blank" rel="noreferrer">docs OpenRouter</a> dan halaman <strong>Limits</strong> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Buat akun di <a href="https://openrouter.ai" target="_blank" rel="noreferrer">openrouter.ai</a>.</li><li>Buka halaman <strong>Credits</strong>, lakukan <strong>top-up</strong> saldo sesuai kebutuhan (fee pembelian credit <strong>5,5%</strong>, minimum top-up <strong>0,80 USD</strong>).</li><li>Buka bagian <strong>API Keys</strong>, klik <strong>Create Key</strong>, beri nama, lalu salin key yang ditampilkan.</li><li>Key ini dipakai sebagai <em>Bearer token</em> di setiap request.</li></ol><div class="danger custom-block"><p class="custom-block-title">🔒 Key hanya ditampilkan sekali</p><p>Sama seperti provider pada umumnya, salin key langsung ke tempat aman (password manager) sebelum menutup dialog. Key yang bocor = saldo kredit-mu bisa dipakai orang lain. Jangan pernah menempelkan key ke chat, forum, atau screenshot.</p></div><div class="tip custom-block"><p class="custom-block-title">💡 Cek sisa kredit lewat API</p><p>OpenRouter menyediakan endpoint <code>GET https://openrouter.ai/api/v1/key</code> yang menampilkan sisa kredit dan limit key kamu — berguna buat diagnostik tanpa membuka dashboard.</p></div><p>API-nya <strong>kompatibel OpenAI penuh</strong> (<em>drop-in</em>): kalau kamu pernah memakai SDK OpenAI, format request/response-nya identik.</p><hr><h2 id="mengaktifkan-openrouter-di-mikazuki-ai" tabindex="-1">Mengaktifkan OpenRouter di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-openrouter-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan OpenRouter di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk OpenRouter:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, pilih <strong>OpenRouter</strong> (native, <em>fixed endpoint</em>).</li><li>Tempel API key yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar akan berisi <strong>ratusan model</strong> dari berbagai lab, jadi lebih panjang dari biasanya.</li><li>Pilih model, atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — terutama <code>context_window</code> — lalu klik simpan.</li></ol><h3 id="contoh-memilih-model" tabindex="-1">Contoh memilih model <a class="header-anchor" href="#contoh-memilih-model" aria-label="Permalink to “Contoh memilih model”">​</a></h3><ul><li>Untuk <strong>coba gratis</strong>: pilih model dengan varian <code>:free</code> (lihat bagian di bawah).</li><li>Untuk <strong>roleplay</strong> yang mulus: model kelas <em>flash/sonnet/haiku</em> dengan varian <code>:nitro</code> — respons cepat dan stabil.</li></ul><div class="tip custom-block"><p class="custom-block-title">Sudah baik dari sananya</p><p>Default <strong>temperature 0.85</strong> Mikazuki sudah dipetakan dengan baik untuk roleplay; kamu tidak perlu mengubahnya kecuali memang ingin gaya jawaban yang sangat berbeda.</p></div><hr><h2 id="model-variant-suffix" tabindex="-1">Model &amp; Variant Suffix <a class="header-anchor" href="#model-variant-suffix" aria-label="Permalink to “Model &amp; Variant Suffix”">​</a></h2><p>Nama model di OpenRouter berformat <code>vendor/model</code>, contohnya <code>google/gemini-2.5-flash</code>. Varian ditambahkan lewat <em>suffix</em> titik dua di belakang nama model:</p><table tabindex="0"><thead><tr><th>Variant</th><th>Fungsi</th></tr></thead><tbody><tr><td><code>:free</code></td><td>Versi gratis model — punya limit pemakaian sendiri (lihat bagian berikutnya)</td></tr><tr><td><code>:nitro</code></td><td>Prioritas throughput/kecepatan — paling pas untuk roleplay</td></tr><tr><td><code>:floor</code></td><td>Prioritas harga termurah di antara provider yang melayani model tsb</td></tr><tr><td><code>:exacto</code></td><td><em>Quality-first</em> untuk tool calling</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Untuk roleplay, biasakan <code>:nitro</code></p><p>Roleplay harus terasa responsif — varian <code>:nitro</code> memprioritaskan kecepatan layanan. Pakai <code>:floor</code> kalau hemat lebih penting, dan <code>:free</code> untuk mencoba-coba tanpa biaya.</p></div><hr><h2 id="free-tier-limit" tabindex="-1">Free Tier &amp; Limit <a class="header-anchor" href="#free-tier-limit" aria-label="Permalink to “Free Tier &amp; Limit”">​</a></h2><p>Ratusan model di OpenRouter punya varian <strong><code>:free</code> yang benar-benar gratis</strong> — limitnya ditentukan oleh <strong>saldo kredit yang pernah kamu top-up</strong>:</p><ul><li>Akun <strong>tanpa kredit</strong>: sekitar <strong>≈ 50 request/hari</strong>.</li><li>Total top-up <strong>≥ 10 USD</strong>: limit naik sekitar <strong>≈ 1.000 request/hari</strong>.</li><li>Tambahan batas laju: sekitar <strong>≈ 20 request/menit</strong>.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Angka bisa berubah</p><p>Angka di atas diberi tanda <strong>&quot;≈&quot;</strong> karena kebijakan free tier sering berubah — selalu cek halaman <strong>Limits</strong> di docs resmi OpenRouter untuk angka terkini. Kalau sering kena limit, opsi paling tenang: pakai model berbayar; biaya per pesan roleplay biasanya sangat kecil.</p></div><hr><h2 id="harga-kredit" tabindex="-1">Harga &amp; Kredit <a class="header-anchor" href="#harga-kredit" aria-label="Permalink to “Harga &amp; Kredit”">​</a></h2><ul><li><strong>Harga pass-through tanpa markup</strong>: harga model yang kamu lihat adalah harga dari lab penyedianya; OpenRouter menambahkan fee di titik pembelian kredit (<strong>5,5%</strong>, minimum top-up 0,80 USD), bukan di harga per token.</li><li><strong>Kredit bisa hangus</strong>: kredit yang dipakai atau <strong>tidak terpakai lama bisa expire</strong> — jangan top-up jumbo sekalian kalau pemakaianmu kecil.</li><li><strong>Auto top-up</strong> tersedia: setting agar saldo otomatis diisi ulang saat menipis, biar tidak tiba-tiba error di tengah obrolan.</li><li><strong>Refund</strong>: ada kebijakan refund untuk kredit yang terpakai di 24 jam pertama dan tidak jadi dipakai; <strong>pembelian via crypto tidak bisa di-refund</strong>.</li><li>Cek sisa kredit/limit kapan saja via <code>GET https://openrouter.ai/api/v1/key</code>.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Jangan kunci angka</p><p>Kami tidak mencantumkan tabel harga per model — ratusan model dan harganya cepat basi. Cek halaman model di <a href="https://openrouter.ai/models" target="_blank" rel="noreferrer">openrouter.ai</a> untuk angka terkini.</p></div><hr><h2 id="privasi-data" tabindex="-1">Privasi &amp; Data <a class="header-anchor" href="#privasi-data" aria-label="Permalink to “Privasi &amp; Data”">​</a></h2><p>Bagian ini penting kalau kamu prihatin soal privasi <em>roleplay</em>-mu:</p><ul><li><strong>Zero logging secara default</strong>: OpenRouter <strong>tidak menyimpan prompt maupun completion</strong> kamu secara default.</li><li><strong>Opt-in logging</strong> memberi <strong>diskon 1%</strong> — kalau kamu mengaktifkannya, chat-mu tersimpan di log mereka. Kalau tidak butuh, biarkan mati.</li><li><strong>Data used for training</strong>: bisa dimatikan lewat toggle di <strong>Privacy settings</strong>.</li><li><strong>Routing EU</strong>: tersedia endpoint <code>https://eu.openrouter.ai</code> untuk <em>data residency</em> di Eropa.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Rekomendasi untuk pengguna Mikazuki</p><p>Untuk roleplay pribadi, pertahankan setelan default (zero logging, no training) — kamu tidak butuh diskon 1%. Kalau sesekali kamu melihat chat-mu muncul di halaman <strong>Usage</strong> seperti prompt yang tersimpan, kemungkinan kamu pernah opt-in logging untuk diskon — matikan lagi di Privacy settings.</p></div><hr><h2 id="byok-di-openrouter-opsional" tabindex="-1">BYOK di OpenRouter (Opsional) <a class="header-anchor" href="#byok-di-openrouter-opsional" aria-label="Permalink to “BYOK di OpenRouter (Opsional)”">​</a></h2><p>OpenRouter juga punya fiturnya sendiri bernama BYOK: kamu bisa memasang key provider lain (Gemini, Claude, dan lainnya) <em>di dalam</em> OpenRouter, dengan kuota inference list-price <strong>$25.000/bulan tanpa fee BYOK</strong> (fee <strong>5%</strong> di atasnya). Untuk pengguna Mikazuki BYOK biasa, ini <strong>opsional</strong> dan jarang dibutuhkan — cukup pakai key OpenRouter kamu sendiri. Kalau penasaran, lihat <a href="./../byok/">Pengenalan BYOK</a>.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>Error 402 Payment Required</summary><p><strong>Kredit kamu habis.</strong> Cek dulu sisa saldo via <code>GET https://openrouter.ai/api/v1/key</code>, lalu top-up di halaman <strong>Credits</strong> openrouter.ai. Tip: atur <strong>auto top-up</strong> biar tidak kejadian lagi di tengah obrolan.</p></details><details class="details custom-block"><summary>Error 429 — terlalu sering</summary><p>Kamu kena limit varian <code>:free</code> — harian (≈ 50 sampai ≈ 1.000 request tergantung top-up) atau per menit (≈ 20). Tunggu reset limit, atau pakai <strong>model berbayar</strong> yang limitnya jauh lebih longgar.</p></details><details class="details custom-block"><summary>Error 404 — no endpoints found</summary><p>Semua provider yang melayani model itu sedang down, atau setelan privasi kamu tidak cocok dengan kebijakan salah satu provider-nya. Coba <strong>model lain</strong> atau varian <code>:nitro</code> — fallback antar provider biasanya langsung menyelesaikan.</p></details><details class="details custom-block"><summary>Jawaban terpotong / berhenti di tengah</summary><p><code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> mungkin terlalu kecil. Naikkan nilainya — tapi ingat <code>max_tokens</code> juga dipotong dari context window sebagai <em>Reserved Output</em>, jadi jangan set berlebihan tanpa menaikkan <code>context_window</code>.</p></details><details class="details custom-block"><summary>Mengapa chat saya muncul di &quot;usage&quot;?</summary><p>Secara default OpenRouter <strong>zero-logging</strong> — prompt/completion tidak disimpan. Kalau chat-mu muncul seolah tersimpan di halaman Usage, kemungkinan kamu pernah <strong>opt-in logging</strong> untuk diskon 1%. Matikan lagi lewat Privacy settings (dan pastikan toggle <em>training</em> di sana juga nonaktif).</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./gemini.html">Google Gemini</a> — panduan padanan untuk provider Gemini.</li><li><a href="./claude.html">Anthropic Claude</a> — panduan padanan untuk provider Claude.</li><li><a href="./systemai.html">System AI</a> — kalau kamu tidak ingin mengurus key dan pembayaran API sendiri.</li></ul>`,48)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};